// And groups predicates with the AND operator between them.
func And(predicates ...predicate.FailurePattern) predicate.FailurePattern {
	return predicate.FailurePattern(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.FailurePattern) predicate.FailurePattern {
	return predicate.FailurePattern(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.FailurePattern) predicate.FailurePattern {
	return predicate.FailurePattern(sql.NotPredicates(p))
}
